package com.zizai.watermark;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.*;
public final class TransferTests {
    static int checks;static void check(boolean c,String why){checks++;if(!c)throw new AssertionError(why);}
    public static void main(String[] args)throws Exception{
        TransferStats s=new TransferStats();check(s.current().fraction<0,"connecting has unknown percentage");s.phase("下载");TransferStats.Snapshot a=s.bytes(0,10000,1000);check(a.fraction==0,"known start is zero");a=s.bytes(2000,10000,2000);check(a.fraction==.2,"real fraction");check(a.speed.equals("2.0 KB/s")&&a.remaining.equals("00:04"),"measured speed and ETA");
        a=s.bytes(10000,10000,3000);check(a.fraction==.99,"not marked saved before MediaStore commit");String amount=a.amount;a=s.phase("登记媒体库");check(a.fraction<0&&a.amount.equals(amount),"registration has unknown percent and retains measured bytes");check(s.complete().fraction==1,"only commit marks completion");
        a=s.bytes(6000,-1,5000);check(a.fraction<0&&a.amount.contains("大小未知"),"chunked size does not fabricate percent");a=s.bytes(1,10000,6000);check(a.speed.equals("—"),"restart resets speed estimate");
        a=s.nativeSample(250,1000,512,2.5,true);check(a.fraction==.25&&a.estimated&&a.amount.contains("约"),"native estimate visibly labeled");check(a.remaining.equals("00:03"),"ETA rounds up");a=s.nativeSample(500,1000,Double.NaN,Double.POSITIVE_INFINITY,false);check(a.speed.equals("—")&&a.remaining.equals("—"),"nonfinite native statistics ignored");
        check(TransferStats.time(3661).equals("01:01:01"),"hour formatting");check(TransferStats.time(-1).equals("—"),"unknown ETA");check(TransferStats.size(1024L*1024*1024).equals("1.0 GB"),"GB formatting");check(TransferStats.size(-1).equals("0 B"),"negative bytes clamped");
        EngineProgress.Sample p=EngineProgress.parse("__WM_PROGRESS__{\"downloaded_bytes\":250,\"total_bytes\":1000,\"speed\":512.0,\"eta\":2}");check(p!=null&&p.bytes==250&&p.total==1000&&!p.estimated,"structured native statistics");p=EngineProgress.parse("__WM_PROGRESS__{\"downloaded_bytes\":1,\"total_bytes\":null,\"total_bytes_estimate\":100,\"speed\":null}");check(p.estimated&&p.total==100&&p.speed<0,"optional native fields");check(EngineProgress.parse("[download] 100%") == null,"ordinary logs not interpreted as saved");check(EngineProgress.parse("__WM_PROGRESS__broken") == null,"malformed structured line skipped");
        String source="https://www.example.org/private/watch?token=1";String jar=SessionCookieJar.netscape(source,"session=abc=xyz; a=2");check(CookieFile.header(jar,source,1).equals("session=abc=xyz; a=2"),"in-app session usable on exact original path");check(CookieFile.header(jar,"https://cdn.example.org/private/watch",1).isEmpty(),"no native cookie leak to CDN");check(CookieFile.header(jar,"https://www.example.org/private/other",1).isEmpty(),"native jar retains URL path scope");check(SessionCookieJar.netscape(source,"a=1\nInjected=yes").isEmpty(),"header injection rejected");check(SessionCookieJar.netscape("http://www.example.org/private/watch","a=1").isEmpty(),"native session HTTPS only");
        for(String url:new String[]{"https://b23.tv/a","https://v.douyin.com/a","https://vm.tiktok.com/a","https://pin.it/a","https://fb.watch/a","https://t.co/a"})check(PlatformRoutes.shortLink(url),"mainstream shortener");check(!PlatformRoutes.shortLink("https://b23.tv.evil.org/a"),"shortener host boundary");check(PlatformRoutes.name("https://m.youtube.com/watch?v=x").equals("YouTube"),"subdomain platform routing");check(PlatformRoutes.name("https://youtube.com.evil.org/a").equals("网页"),"platform host boundary");
        check(BundledEngine.older("2025.01.01",BundledEngine.VERSION),"old installed engine upgraded");check(!BundledEngine.older("2026.09.01",BundledEngine.VERSION),"new user update preserved");check(!BundledEngine.older(BundledEngine.VERSION,BundledEngine.VERSION),"same bundle not repeatedly replaced");check(BundledEngine.older("",BundledEngine.VERSION),"missing engine recovered");check(BundledEngine.version(new File(args[0])).equals(BundledEngine.VERSION),"actual bundled script version read without execution");
        Path directory=Files.createTempDirectory("engine-upgrade-check"),installed=directory.resolve("yt-dlp");try{
            Files.writeString(installed,"old script");try{BundledEngine.install(installed.toFile(),new ByteArrayInputStream("corrupted".getBytes()));throw new AssertionError("bad bundle installed");}catch(IOException expected){checks++;}check(Files.readString(installed).equals("old script"),"failed checksum preserves old engine");
            try(InputStream in=new FileInputStream(args[0])){BundledEngine.install(installed.toFile(),in);}check(BundledEngine.version(installed.toFile()).equals(BundledEngine.VERSION),"verified bundle installed atomically");
            check(Files.list(directory).count()==1,"upgrade temporary files cleaned");
        }finally{Files.deleteIfExists(installed);Files.deleteIfExists(directory);}
        Path sourceFile=Paths.get(args[1]).toAbsolutePath(),output=Paths.get(args[2]).toAbsolutePath();Files.deleteIfExists(output);List<EngineProgress.Sample> events=new ArrayList<>();
        NativeProcess.run(EngineCommand.build("python3",new File(args[0]).getAbsolutePath(),Arrays.asList("--enable-file-urls","--ignore-config","--no-warnings","--progress","--newline","--progress-delta","0.3","--progress-template",EngineProgress.TEMPLATE,"--progress-template",EngineProgress.POST_TEMPLATE,"-o",output.toString(),sourceFile.toUri().toString())),Collections.emptyMap(),new AtomicBoolean(),15000,line->{EngineProgress.Sample event=EngineProgress.parse(line);if(event!=null)events.add(event);});
        // Tiny local fixtures may finish inside the progress interval and emit only the final sample.
        check(!events.isEmpty(),"real native engine emits structured progress");p=events.get(events.size()-1);check(p.bytes==Files.size(sourceFile)&&p.total==Files.size(sourceFile),"real engine measured bytes match source");check(Arrays.equals(Files.readAllBytes(sourceFile),Files.readAllBytes(output)),"real engine produces uncorrupted media");
        System.out.println("PASS transfer: "+checks+" checks; real ZIP download progress and exact output");
    }
}
